def maxPathSum(root: Optional[TreeNode]) -> int:
    if not root:
        return float('-inf')

    def get_all_nodes(node):
        if not node:
            return []
        return [node] + get_all_nodes(node.left) + get_all_nodes(node.right)

    nodes = get_all_nodes(root)

    def path_exists(u, v):
        path1 = get_path_to(root, u)
        path2 = get_path_to(root, v)
        if not path1 or not path2:
            return False
        i = 0
        while i < len(path1) and i < len(path2) and path1[i] == path2[i]:
            i += 1
        lca_path = path1[i-1:]
        combined = lca_path[::-1] + path2[i:]
        return len(combined) == len(set(combined))

    def get_path_to(curr, target):
        if not curr:
            return None
        if curr == target:
            return [curr]
        left = get_path_to(curr.left, target)
        if left:
            return [curr] + left
        right = get_path_to(curr.right, target)
        if right:
            return [curr] + right
        return None

    def get_simple_path_sum(u, v):
        path1 = get_path_to(root, u)
        path2 = get_path_to(root, v)
        i = 0
        while i < len(path1) and i < len(path2) and path1[i] == path2[i]:
            i += 1
        lca_path = path1[i-1:]
        combined = lca_path[::-1] + path2[i:]
        seen = set()
        for node in combined:
            if node in seen:
                return float('-inf')
            seen.add(node)
        return sum(n.val for n in combined)

    max_sum = float('-inf')
    for i in range(len(nodes)):
        for j in range(i, len(nodes)):
            s = get_simple_path_sum(nodes[i], nodes[j])
            if s > max_sum:
                max_sum = s
    return max_sum

